/* @lc app=leetcode id=3575 lang=kotlin */ class Solution { fun goodSubtreeSum(vals: IntArray, par: IntArray): Int = vals.size.let { n -> (n - 1 downTo 0).fold(Array(n) { LongArray(1024) { if (it == 0) 0L else -1L } }) { dp, v -> vals[v].toString().map { it - '0' }.let { ds -> ds.fold(0) { m, d -> m or (1 shl d) }.let { dm -> dp.also { _ -> if (ds.distinct().size == ds.size) (1023 downTo 0).filter { it and dm == 0 && dp[v][it] >= 0 }.forEach { m -> dp[v][m or dm] = maxOf(dp[v][m or dm], dp[v][m] + vals[v]) } }.also { _ -> if (v > 0) LongArray(1024) { -1L }.let { nw -> (0 until 1024).filter { dp[par[v]][it] >= 0 }.forEach { a -> ((1023 xor a).let { comp -> generateSequence(comp) { b -> if (b == 0) null else (b - 1) and comp }.filter { dp[v][it] >= 0 }.forEach { b -> nw[a or b] = maxOf(nw[a or b], dp[par[v]][a] + dp[v][b]) } }) }.let { nw.copyInto(dp[par[v]]) } } } } } }.let { dp -> dp.sumOf { it.max() } % 1_000_000_007L }.toInt() } }